from backend.depo_platform.service_runtime import create_service_app
from backend.depo_platform.odata import ServiceCapability, create_odata_catalog_router
from .router import router
app = create_service_app(title="DEPO Data Product Service", version="1.0.0", dependencies=("postgres",))
app.include_router(create_odata_catalog_router(service_name="DEPODataProducts", capabilities=[ServiceCapability("Submit release request", "/api/v1/data-products/change-requests/submit", "POST", "Submit an exact product version for review without packaging"), ServiceCapability("Release request", "/api/v1/data-products/change-requests/{product_version}", description="Inspect retained release scope and verified package delivery"), ServiceCapability("Release decision", "/api/v1/data-products/change-requests/{product_version}", "POST", "Review, authorize, execute or reconcile a native product release"), ServiceCapability("Preview", "/api/v1/data-products/preview", "POST", "Validate immutable artifact references and product contract"), ServiceCapability("Publish", "/api/v1/data-products/publish", "POST", "Package and publish an approved data product"), ServiceCapability("Reconcile", "/api/v1/data-products/reconcile", "POST", "Reconcile durable pending catalog registrations"), ServiceCapability("Retry catalog", "/api/v1/data-products/{product_version}/retry-catalog", "POST", "Retry an outbox-style catalog registration"), ServiceCapability("Manifest", "/api/v1/data-products/{product_version}/manifest", description="Read immutable package manifest"), ServiceCapability("Download", "/api/v1/data-products/{product_version}/download", description="Download immutable product package")]))
app.include_router(router, prefix="/api/v1")
